import unittest
from subject import total


class TotalTests(unittest.TestCase):
    # 判準來源：題述規格；(2,False)=40、(3,False)=70 為已確認例子

    def test_confirmed_examples(self):
        self.assertEqual(total(2, False), 40)
        self.assertEqual(total(3, False), 70)

    def test_tier_boundaries_not_remote(self):
        # 抓邊界 off-by-one（<= 誤寫為 <）與固定回傳
        cases = {0: 40, 2: 40, 3: 70, 5: 70, 6: 100, 50: 100}
        for w, exp in cases.items():
            with self.subTest(weight=w):
                self.assertEqual(total(w, False), exp)

    def test_remote_adds_20(self):
        # 抓忽略 remote 或加錯金額
        cases = {0: 60, 2: 60, 3: 90, 5: 90, 6: 120}
        for w, exp in cases.items():
            with self.subTest(weight=w):
                self.assertEqual(total(w, True), exp)

    def test_negative_weight_rejected(self):
        # 抓缺少守衛或邊界寫成 <= 0 / < -1
        for w in (-1, -100):
            for r in (False, True):
                with self.subTest(weight=w, remote=r):
                    with self.assertRaisesRegex(ValueError, "^invalid-weight$"):
                        total(w, r)

    def test_zero_is_valid(self):
        self.assertEqual(total(0, False), 40)

import unittest
from subject import route


class RouteTests(unittest.TestCase):
    # 判準來源：題目規格；已確認例子 route(0,True)=weekday、route(5,True)=weekend

    def test_confirmed_examples(self):
        self.assertEqual(route(0, True), "weekday")
        self.assertEqual(route(5, True), "weekend")

    def test_weekday_boundaries_enabled(self):
        # 規格：day 0..4 -> weekday；4 為上界，抓 >=4 或 >4 邊界錯
        for d in (0, 1, 2, 3, 4):
            self.assertEqual(route(d, True), "weekday", d)

    def test_weekend_boundaries_enabled(self):
        # 規格：day 5..6 -> weekend；抓只認 5 或邊界偏移
        for d in (5, 6):
            self.assertEqual(route(d, True), "weekend", d)

    def test_disabled_returns_paused_for_all_valid_days(self):
        # 規格：合法 day 且 enabled=False -> paused；抓忽略 enabled
        for d in range(7):
            self.assertEqual(route(d, False), "paused", d)

    def test_invalid_day_out_of_range(self):
        # 規格：day 須為 0..6；抓 -1、7 邊界放行
        for d in (-1, 7, 100):
            for en in (True, False):
                with self.assertRaisesRegex(ValueError, "^invalid-day$"):
                    route(d, en)

    def test_invalid_day_string_rejected_even_when_disabled(self):
        # 規格：先驗 day，再看 enabled；抓先回 paused 跳過驗證
        for en in (True, False):
            with self.assertRaisesRegex(ValueError, "^invalid-day$"):
                route("3", en)

import unittest
from subject import route


class RouteTests(unittest.TestCase):
    # 判準來源：題目規格與已確認例子 route(0,True)=weekday、route(5,True)=weekend

    def test_confirmed_examples(self):
        # 抓「固定回傳同一值」的錯誤
        self.assertEqual(route(0, True), "weekday")
        self.assertEqual(route(5, True), "weekend")

    def test_weekday_weekend_boundary(self):
        # 規格：0..4 weekday、5..6 weekend；抓 4/5 分界錯位（如 >=4 或 >=6）
        for d in (0, 1, 2, 3, 4):
            self.assertEqual(route(d, True), "weekday", d)
        for d in (5, 6):
            self.assertEqual(route(d, True), "weekend", d)

    def test_disabled_returns_paused_for_all_valid_days(self):
        # 規格：合法 day 且 enabled=False -> paused；抓忽略 enabled 的錯誤
        for d in range(7):
            self.assertEqual(route(d, False), "paused", d)

    def test_out_of_range_rejected_even_when_disabled(self):
        # 規格：先驗 day；抓範圍邊界錯（-1、7）及先判 enabled 再驗 day 的順序錯
        for d in (-1, 7):
            for en in (True, False):
                with self.assertRaisesRegex(ValueError, "^invalid-day$"):
                    route(d, en)

    def test_non_integer_rejected(self):
        # 規格：day 必須為整數；字串拒絕案例
        for d in ("0", "5"):
            for en in (True, False):
                with self.assertRaisesRegex(ValueError, "^invalid-day$"):
                    route(d, en)

import unittest
from subject import route


class RouteTests(unittest.TestCase):
    # 判準來源：題目規格；預期值依規格人工推導後固定為字面值。

    def test_confirmed_examples(self):
        # 已確認例子：route(0,True)=weekday、route(5,True)=weekend
        self.assertEqual(route(0, True), "weekday")
        self.assertEqual(route(5, True), "weekend")

    def test_weekday_boundary_4(self):
        # 規格：day 0..4 -> weekday；抓 >=4 誤判成 weekend 的邊界錯
        self.assertEqual(route(4, True), "weekday")

    def test_weekday_middle(self):
        for d in (1, 2, 3):
            self.assertEqual(route(d, True), "weekday")

    def test_weekend_upper_6(self):
        # 規格：day 5..6 -> weekend；抓上界 6 處理錯
        self.assertEqual(route(6, True), "weekend")

    def test_disabled_paused_all_valid_days(self):
        # 規格：合法 day 且 enabled=False -> paused（平日、週末都要）
        for d in (0, 4, 5, 6):
            self.assertEqual(route(d, False), "paused")

    def test_invalid_below_range(self):
        # -1 為非法；抓下界守衛遺漏
        with self.assertRaisesRegex(ValueError, "^invalid-day$"):
            route(-1, True)

    def test_invalid_above_range(self):
        # 7 為非法；抓上界守衛遺漏（否則會回 weekend）
        with self.assertRaisesRegex(ValueError, "^invalid-day$"):
            route(7, True)

    def test_invalid_string_day(self):
        # 非整數拒絕；理由需為 invalid-day（非 TypeError 比較錯）
        with self.assertRaisesRegex(ValueError, "^invalid-day$"):
            route("3", True)

    def test_day_validated_before_enabled(self):
        # 規格：先驗 day；enabled=False 時非法 day 仍須拒絕，不可回 paused
        for bad in (-1, 7, "0"):
            with self.assertRaisesRegex(ValueError, "^invalid-day$"):
                route(bad, False)

import unittest
from subject import route


class RouteTests(unittest.TestCase):
    # 判準來源：題目規格與已確認例子 route(0,True)=weekday、route(5,True)=weekend

    def test_confirmed_examples(self):
        self.assertEqual(route(0, True), "weekday")
        self.assertEqual(route(5, True), "weekend")

    def test_weekday_boundary_and_all_weekdays(self):
        # 抓：邊界寫錯 (>=4 / >=6) 或固定回傳
        for d in range(0, 5):
            self.assertEqual(route(d, True), "weekday", d)

    def test_weekend_all_days(self):
        for d in (5, 6):
            self.assertEqual(route(d, True), "weekend", d)

    def test_disabled_returns_paused_for_every_valid_day(self):
        # 抓：忽略 enabled
        for d in range(0, 7):
            self.assertEqual(route(d, False), "paused", d)

    def test_out_of_range_rejected(self):
        # 抓：範圍守衛缺失或 off-by-one（-1、7 是最近的非法值）
        for d in (-1, 7, 100):
            with self.assertRaisesRegex(ValueError, "^invalid-day$"):
                route(d, True)

    def test_invalid_day_checked_before_enabled(self):
        # 規格「先驗 day」：enabled=False 也須拒絕，而非回 paused
        for d in (-1, 7, "3"):
            with self.assertRaisesRegex(ValueError, "^invalid-day$"):
                route(d, False)

    def test_string_day_rejected(self):
        # 抓：缺型別檢查（字串會在比較時拋 TypeError 而非 ValueError）
        with self.assertRaisesRegex(ValueError, "^invalid-day$"):
            route("0", True)
